class Solution {
public:
    std::vector<int> findArray(std::vector<int>& pref) {
        int n = pref.size();
        std::vector<int> res(n);
        res[0] = pref[0];
        for (int i = 1; i < n; i++) {
            res[i] = pref[i - 1] ^ pref[i];
        }
        return res;
    }
};

class Solution {
    public int[] findArray(int[] pref) {
        int n = pref.length;
        int[] res = new int[n];
        res[0] = pref[0];
        for (int i = 1; i < n; i++) {
            res[i] = pref[i - 1] ^ pref[i];
        }
        return res;
    }
}

